// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/shift", wrapper.GetCashShift)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/shifts", wrapper.OpenCashShift)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/shifts/{shiftId}/close", wrapper.CloseCashShift)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/reports/x", wrapper.GetCashXReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/shifts/{shiftId}/z-report", wrapper.GetCashZReport)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/shifts/{shiftId}/z-report/nonce", wrapper.IssueZReportNonce)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/shifts/{shiftId}/z-report/printed", wrapper.MarkZReportPrinted)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/sales", wrapper.CreateCashSale)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/balance-top-ups", wrapper.CreateBalanceTopUp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/transactions", wrapper.CreateCashTransaction)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/operations", wrapper.ListCashOperations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/receipts/{transactionId}", wrapper.GetCashReceipt)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/cash/receipts/{transactionId}/refund", wrapper.RefundCashReceipt)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/catalog", wrapper.GetCashCatalog)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/products", wrapper.ListCashProducts)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/cash/customers", wrapper.SearchCashCustomers)
	})

	return r
}

